fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // list.len() = n, we assume 1 <= k < n (1-based indexing)
    let n = list.len();
    // Pre-allocate space for the new list of length n - 1
    let mut new_list = Vec::with_capacity(n - 1);

    // Copy everything before the k-th element (in 1-based indexing that is index k-1 in 0-based)
    new_list.extend_from_slice(&list[..k - 1]);

    // Copy everything after the k-th element
    new_list.extend_from_slice(&list[k..]);

    new_list
}

